const body = $json.body || {};
const headers = $json.headers || {};
const authOk = String(headers['x-api-key'] || '') === String($env.CRM_API_KEY || '');

function tel(v) {
  const d = String(v || '').replace(/\D/g, '');
  if (!d) return '';
  if (d.length === 10 || d.length === 11) return '55' + d;
  if (d.length === 12 || d.length === 13) return d;
  return d;
}

const telefone = tel(body.telefone || body.phone);
const email = String(body.email || '').trim().toLowerCase();
const nome = String(body.nome || body.name || '').trim();
const empresa = String(body.empresa || '').trim();
const nicho = String(body.nicho || '').trim();
const volume = Math.max(0, Number(body.volume_mensal || 0));

const telefoneValido = /^55\d{10,11}$/.test(telefone);
const emailValido = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);

let score = 0;
if (telefoneValido) score += 25;
if (emailValido) score += 15;
if (empresa) score += 10;
if (nicho) score += 10;
if (volume >= 50000) score += 40;
else if (volume >= 10000) score += 30;
else if (volume >= 1000) score += 20;
else if (volume > 0) score += 10;

const temperatura = score >= 70 ? 'quente' : score >= 45 ? 'morno' : 'frio';
const valido = authOk && (telefoneValido || emailValido) && Boolean(nome);

return [{ json: {
  authOk, valido, nome, email, telefone_e164: telefoneValido ? telefone : null,
  empresa, nicho, volume_mensal: volume, score, temperatura,
  origem: String(body.utm_source || body.origem || 'ads'),
  campanha_ads: String(body.campanha_ads || body.utm_campaign || ''),
  conjunto_ads: String(body.conjunto_ads || ''),
  anuncio_ads: String(body.anuncio_ads || ''),
  utm: {
    source: body.utm_source || null, medium: body.utm_medium || null,
    campaign: body.utm_campaign || null, content: body.utm_content || null,
    term: body.utm_term || null
  },
  motivo: !authOk ? 'api_key_invalida'
        : !nome ? 'nome_ausente'
        : (!telefoneValido && !emailValido) ? 'contato_invalido' : null
} }];

const body = $json.body || {};
const headers = $json.headers || {};
const authOk = String(headers['x-api-key'] || '') === String($env.CRM_API_KEY || '');

const PLANOS = {
  starter: { creditos: 5000,  limite_dia: 500,   limite_hora: 60  },
  pro:     { creditos: 20000, limite_dia: 2000,  limite_hora: 200 },
  scale:   { creditos: 60000, limite_dia: 6000,  limite_hora: 500 }
};

const plano = String(body.plano || 'starter').toLowerCase();
const cfg = PLANOS[plano];
const nomeEmpresa = String(body.nome_empresa || '').trim();
const email = String(body.email || '').trim().toLowerCase();
const provider = String(body.provider || 'cloud_api');

function tel(v) {
  const d = String(v || '').replace(/\D/g, '');
  if (d.length === 10 || d.length === 11) return '55' + d;
  return d;
}

const valido = authOk && Boolean(cfg) && Boolean(nomeEmpresa) &&
               ['cloud_api', 'gateway'].includes(provider);

return [{ json: {
  authOk, valido, plano, nome_empresa: nomeEmpresa,
  responsavel: String(body.responsavel || ''), email,
  telefone_e164: tel(body.telefone), provider,
  provider_config: body.provider_config || {},
  lead_id: body.lead_id || null,
  creditos: cfg ? cfg.creditos : 0,
  limite_diario: cfg ? cfg.limite_dia : 0,
  limite_hora: cfg ? cfg.limite_hora : 0,
  janela_inicio: Number(body.janela_inicio ?? 9),
  janela_fim: Number(body.janela_fim ?? 20),
  motivo: !authOk ? 'api_key_invalida'
        : !cfg ? 'plano_invalido'
        : !nomeEmpresa ? 'nome_empresa_ausente'
        : 'provider_invalido'
} }];

const body = $json.body || {};
const headers = $json.headers || {};
const authOk = String(headers['x-api-key'] || '') === String($env.CRM_API_KEY || '');

const clienteId = String(body.cliente_id || '').trim();
const origem = String(body.origem_consentimento || '').trim();
const texto = String(body.texto_consentimento || '').trim();
const dataColeta = String(body.data_coleta || '').trim();
const responsavel = String(body.responsavel_declaracao || '').trim();

const ORIGENS = ['formulario_site','checkout','opt_in_whatsapp','evento','cadastro_loja','app'];

// Consentimento e obrigatorio e a origem precisa ser uma das declaradas.
const consentimentoOk =
  ORIGENS.includes(origem) && texto.length >= 20 &&
  /^\d{4}-\d{2}-\d{2}$/.test(dataColeta) && responsavel.length >= 3;

const uuidOk = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(clienteId);

function tel(v) {
  const d = String(v || '').replace(/\D/g, '');
  if (d.length === 10 || d.length === 11) return '55' + d;
  if (d.length === 12 || d.length === 13) return d;
  return '';
}

const brutos = Array.isArray(body.contatos) ? body.contatos : [];
const vistos = new Set();
const contatos = [];
let rejeitados = 0;

for (const c of brutos) {
  const telefone = tel(c.telefone || c.phone || c.numero);
  if (!/^55\d{10,11}$/.test(telefone) || vistos.has(telefone)) { rejeitados++; continue; }
  vistos.add(telefone);
  const { telefone: _t, phone: _p, numero: _n, nome: _nm, name: _na, ...extras } = c;
  contatos.push({
    telefone_e164: telefone,
    nome: String(c.nome || c.name || '').trim() || null,
    campos: extras
  });
}

const valido = authOk && uuidOk && consentimentoOk && contatos.length > 0;

return [{ json: {
  authOk, valido, cliente_id: clienteId,
  nome_lista: String(body.nome_lista || 'Lista sem nome').trim(),
  origem_consentimento: origem, texto_consentimento: texto,
  data_coleta: dataColeta || null, responsavel_declaracao: responsavel,
  contatos, total_recebido: brutos.length,
  total_valido: contatos.length, total_rejeitado: rejeitados,
  motivo: !authOk ? 'api_key_invalida'
        : !uuidOk ? 'cliente_id_invalido'
        : !consentimentoOk ? 'prova_de_consentimento_incompleta'
        : 'nenhum_contato_valido'
} }];

const hora = Number($now.setZone('America/Sao_Paulo').toFormat('H'));

return items.map(item => {
  const c = item.json;
  const inicio = Number(c.janela_inicio ?? 9);
  const fim = Number(c.janela_fim ?? 20);
  const naJanela = hora >= inicio && hora < fim;
  const temSaldo = Number(c.creditos_saldo || 0) > 0;
  const templateOk = c.provider === 'gateway'
    ? Boolean(c.corpo)
    : (Boolean(c.nome_meta) && c.template_status === 'approved');

  const podeOperar = naJanela && temSaldo && templateOk;

  return { json: { ...c, hora, naJanela, temSaldo, templateOk, podeOperar,
    bloqueio: podeOperar ? null
      : !naJanela ? 'fora_da_janela'
      : !temSaldo ? 'sem_credito'
      : 'template_invalido' } };
});

const campanha = $('25 - Guardrails Cliente e Janela').first().json;
const contato = $json.contato_id ? $json : null;

if (!contato) {
  return [{ json: { temContato: false, bloqueio: 'campanha_sem_contatos_restantes',
                    cliente_id: campanha.cliente_id, campanha_id: campanha.campanha_id } }];
}

const primeiroNome = String(contato.nome || 'cliente').split(' ')[0];
const cfg = campanha.provider_config || {};
const RODAPE = '\n\nResponda SAIR para nao receber mais mensagens.';

let url, headers, body;

if (campanha.provider === 'cloud_api') {
  const versao = $env.GRAPH_API_VERSION || 'v23.0';
  const numeroId = cfg.numero_id || $env.WA_PHONE_NUMBER_ID;
  url = 'https://graph.facebook.com/' + versao + '/' + numeroId + '/messages';
  headers = {
    Authorization: 'Bearer ' + (cfg.token || $env.META_ACCESS_TOKEN),
    'Content-Type': 'application/json'
  };
  // No Cloud API o opt-out vive no proprio template aprovado, com botao.
  body = {
    messaging_product: 'whatsapp',
    to: contato.telefone_e164,
    type: 'template',
    template: {
      name: campanha.nome_meta,
      language: { code: campanha.idioma || 'pt_BR' },
      components: [{ type: 'body', parameters: [{ type: 'text', text: primeiroNome }] }]
    }
  };
} else {
  // Gateway generico (Evolution e compativeis). O rodape de opt-out
  // e injetado aqui porque nao existe template aprovado para carrega-lo.
  const base = String(cfg.base_url || $env.GATEWAY_BASE_URL || '').replace(/\/+$/, '');
  const instancia = cfg.instancia || 'default';
  const texto = String(campanha.corpo || '')
    .replace(/\{\{\s*nome\s*\}\}/g, primeiroNome) + RODAPE;
  url = base + '/message/sendText/' + instancia;
  headers = { apikey: cfg.api_key || $env.GATEWAY_API_KEY, 'Content-Type': 'application/json' };
  body = { number: contato.telefone_e164, text: texto };
}

return [{ json: {
  temContato: true,
  cliente_id: campanha.cliente_id,
  campanha_id: campanha.campanha_id,
  contato_id: contato.contato_id,
  telefone_e164: contato.telefone_e164,
  provider: campanha.provider,
  limite_hora: campanha.limite_hora,
  limite_diario: campanha.limite_diario,
  provider_url: url, provider_headers: headers, provider_body: body
} }];

const ctx = $('28 - Montar Mensagem e Requisicao').first().json;
const v = $json || {};

const enviadosHora = Number(v.enviados_hora || 0);
const enviadosDia = Number(v.enviados_dia || 0);
const saldo = Number(v.saldo || 0);
const limiteHora = Number(ctx.limite_hora || 60);
const limiteDia = Number(ctx.limite_diario || 500);

const liberado = saldo > 0 && enviadosHora < limiteHora && enviadosDia < limiteDia;

return [{ json: { ...ctx,
  volume: { enviadosHora, enviadosDia, limiteHora, limiteDia, saldo },
  liberado,
  bloqueio: liberado ? null
    : saldo <= 0 ? 'sem_credito'
    : enviadosHora >= limiteHora ? 'limite_hora'
    : 'limite_dia' } }];

const ctx = $('31 - Decidir Envio').first().json;
const r = $json || {};

// Cloud API devolve messages[0].id. Gateways variam: key.id, id, message_id.
const messageId =
  r.messages?.[0]?.id || r.key?.id || r.id || r.message_id || r.messageId || null;

const erro = r.error || r.erro || (r.status >= 400 ? r : null);
const ok = Boolean(messageId) && !erro;

return [{ json: { ...ctx,
  ok, message_id: messageId,
  status: ok ? 'sent' : 'failed',
  retorno: r,
  erro: erro || null } }];

const body = $json.body || $json;
const saidas = [];

// Formato Meta Cloud API
for (const entry of body.entry || []) {
  for (const change of entry.changes || []) {
    for (const msg of (change.value || {}).messages || []) {
      saidas.push({
        telefone_e164: msg.from,
        message_id: msg.id,
        texto: msg.text?.body || msg.button?.text
             || msg.interactive?.button_reply?.title || ''
      });
    }
  }
}

// Formato gateway (Evolution e compativeis)
if (!saidas.length && (body.data || body.message)) {
  const d = body.data || body;
  const jid = d.key?.remoteJid || d.from || '';
  if (!d.key?.fromMe && jid && !jid.includes('@g.us')) {
    saidas.push({
      telefone_e164: String(jid).split('@')[0].replace(/\D/g, ''),
      message_id: d.key?.id || d.id || null,
      texto: d.message?.conversation
          || d.message?.extendedTextMessage?.text
          || d.text || ''
    });
  }
}

if (!saidas.length) return [{ json: { ignorado: true, isOptOut: false } }];

const SAIDA = ['sair','parar','cancelar','remover','descadastrar','stop','pare'];
const DENUNCIA = ['spam','denunciar','denuncia','procon','advogado','processar'];

return saidas.map(s => {
  const limpo = String(s.texto || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z\s]/g, '').trim();
  const palavras = limpo.split(/\s+/);

  const isOptOut = SAIDA.some(p => palavras.includes(p));
  const isDenuncia = DENUNCIA.some(p => limpo.includes(p));

  return { json: { ...s, ignorado: false, isOptOut: isOptOut || isDenuncia,
    isDenuncia, palavra: palavras.find(p => SAIDA.includes(p)) || (isDenuncia ? 'denuncia' : null),
    payload: body } };
});

const q = $json.query || {};
const headers = $json.headers || {};
const authOk = String(headers['x-api-key'] || '') === String($env.CRM_API_KEY || '');
const clienteId = String(q.cliente_id || '').trim();
const uuidOk = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(clienteId);

return [{ json: { valido: authOk && uuidOk, cliente_id: clienteId,
  motivo: !authOk ? 'api_key_invalida' : 'cliente_id_invalido' } }];
